using System.Reflection;
using GameLauncherGUI;
using Newtonsoft.Json.Linq;

internal static class RedesignChecks
{
    internal const string NativeFixture="{version:1,data:[{group_name:'/graphics',options:[{name:'TextureQuality',type:'string_list',value:'High',index:2,values:['Low','Medium','High']}]},{group_name:'/graphics/basic',options:[{name:'FilmGrain',type:'bool',value:true}]},{group_name:'/graphics/advanced',options:[{name:'CrowdDensity',type:'string_list',value:'High',index:2,values:['Low','Medium','High']}]},{group_name:'/video/display',options:[{name:'MaximumFPS_Value',type:'int',value:60,min_value:10,max_value:240}]},{group_name:'/controls',options:[{name:'MouseSensitivity',type:'float',value:4}]}]}";
    private static int checks;
    private static void Check(bool value,string message){if(!value)throw new Exception(message);checks++;}
    private static void Reject(Action action){try{action();}catch(Exception ex)when(ex is IOException or InvalidDataException or ArgumentException or Newtonsoft.Json.JsonException){checks++;return;}throw new Exception("Unsafe graphics change accepted");}
    private static IEnumerable<Control> Children(Control parent)=>parent.Controls.Cast<Control>().SelectMany(c=>new[]{c}.Concat(Children(c)));
    internal static void Run(bool ui)
    {
        string root=Path.Combine(Path.GetTempPath(),"PlaySpaceRedesign-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        try{
            string ini="; keep\n[/Script/Engine.GameUserSettings]\nResolutionSizeX=1920\nResolutionSizeY=1080\nFrameRateLimit=144\nbUseVSync=False\nFullscreenMode=1\n[ScalabilityGroups]\nsg.TextureQuality=3\nsg.ShadowQuality=0\nsg.ResolutionQuality=75\n[Other]\nCustom=1";string path=Path.Combine(root,"GameUserSettings.ini");File.WriteAllText(path,ini);
            var profile=GamePerformanceController.ReadConfig(path);Check(profile.ResolutionWidth==1920&&profile.TargetFps==144&&profile.RenderScale==75,"Current Unreal settings not loaded");Check(profile.DetailLevels["TextureQuality"]==3&&profile.DetailLevels["ShadowQuality"]==0,"Per-setting levels lost");profile.DetailLevels["ShadowQuality"]=1;var edited=GamePerformanceController.EditIni(ini,profile,new(1920,1080));Check(edited.Contains("sg.ShadowQuality=1")&&edited.Contains("sg.TextureQuality=3")&&edited.Contains("Custom=1"),"Granular editing changed unrelated settings");
            profile.DetailLevels["NotASetting"]=3;profile.DetailLevels["EffectsQuality"]=999;var copy=profile.Copy();Check(!copy.DetailLevels.ContainsKey("NotASetting")&&!copy.DetailLevels.ContainsKey("EffectsQuality"),"Untrusted Unreal keys not filtered");copy.DetailLevels["TextureQuality"]=0;Check(profile.DetailLevels["TextureQuality"]==3,"Profile dictionary not copied");
            profile.UnlimitedFps=true;Check(GamePerformanceController.EditIni(ini,profile,new(1920,1080)).Contains("FrameRateLimit=0"),"Unreal unlimited FPS not applied");Check(GamePerformanceController.BuildArguments(new(){SteamAppId="730",ExePath="cs2.exe"},profile,new(1920,1080)).Last()=="0","CS2 unlimited FPS not applied");
            File.WriteAllText(path,ini.Replace("FrameRateLimit=144","FrameRateLimit=0.00000"));var unlimited=GamePerformanceController.ReadConfig(path);Check(unlimited.UnlimitedFps&&unlimited.TargetFps==60,"Current unlimited/decimal FPS not read");
            var definitions=CyberpunkGraphics.Describe(NativeFixture);Check(definitions.Length==4&&!definitions.Any(s=>s.Key.Contains("Mouse")),"Non-graphics controls exposed");var changes=new Dictionary<string,string>{{"/graphics|TextureQuality","Medium"},{"/graphics/basic|FilmGrain","false"},{"/video/display|MaximumFPS_Value","120"}};
            var previousCulture=System.Globalization.CultureInfo.CurrentCulture;try{System.Globalization.CultureInfo.CurrentCulture=System.Globalization.CultureInfo.GetCultureInfo("ru-RU");var floatSettings=CyberpunkGraphics.Describe("{data:[{group_name:'/graphics/basic',options:[{name:'Sharpness',type:'float',value:0.5,min_value:0,max_value:1}]}]}");Check(floatSettings[0].Value=="0.5","Native numeric culture changed value");}finally{System.Globalization.CultureInfo.CurrentCulture=previousCulture;}
            var native=JObject.Parse(CyberpunkGraphics.Edit(NativeFixture,changes));Check(native.SelectToken("data[0].options[0].value")!.Value<string>()=="Medium"&&native.SelectToken("data[0].options[0].index")!.Value<int>()==1,"Enum value/index mismatch");Check(native.SelectToken("data[1].options[0].value")!.Type==JTokenType.Boolean&&native.SelectToken("data[3].options[0].value")!.Type==JTokenType.Integer,"Native value type changed");Check(native.SelectToken("data[4].options[0].value")!.Value<int>()==4,"Mouse settings modified");
            Reject(()=>CyberpunkGraphics.Edit(NativeFixture,new(){{"/controls|MouseSensitivity","9"}}));Reject(()=>CyberpunkGraphics.Edit(NativeFixture,new(){{"/graphics|TextureQuality","Extreme"}}));Reject(()=>CyberpunkGraphics.Edit(NativeFixture,new(){{"/video/display|MaximumFPS_Value","999"}}));Reject(()=>CyberpunkGraphics.Edit(NativeFixture,new(){{"/video/display|MaximumFPS_Value","NaN"}}));Reject(()=>CyberpunkGraphics.Edit(NativeFixture,new(){{"/video/display|MaximumFPS_Value","60.5"}}));
            string json=Path.Combine(root,"UserSettings.json");File.WriteAllText(json,NativeFixture,System.Text.Encoding.Unicode);byte[] original=File.ReadAllBytes(json);CyberpunkGraphics.Apply(json,changes);Check(File.ReadAllBytes(json+".playspace-backup").SequenceEqual(original),"Native original backup lost");CyberpunkGraphics.Apply(json,new(){{"/graphics|TextureQuality","Low"}});Check(File.ReadAllBytes(json+".playspace-backup").SequenceEqual(original),"Native backup overwritten");CyberpunkGraphics.Restore(json);Check(File.ReadAllBytes(json).SequenceEqual(original),"Native restore not exact");
            var game=new GameInfo{Name="Cyberpunk 2077",SteamAppId="1091500",ExePath=Path.Combine(root,"Cyberpunk2077.exe"),Performance=new(){ConfigFile=json,NativeOptions=changes}};Check(GamePerformanceController.Backend(game)==PerformanceBackend.Cyberpunk&&GamePerformanceController.Config(game,game.Performance)==json,"Cyberpunk backend not resolved");Check(GamePerformanceController.BuildArguments(game,game.Performance,new(1920,1080)).Length==0,"Invented Cyberpunk launch flags");
            Check(BenchmarkCatalog.All.Length>=300&&BenchmarkCatalog.All.All(s=>s.Fps>0&&s.Source.StartsWith("https://")),"Benchmark provenance missing");Check(BenchmarkCatalog.GpuKey("RTX 3060 Ti")=="RTX 3060 TI"&&BenchmarkCatalog.GpuKey("RTX 3060 Laptop GPU")=="laptop","GPU variants mixed");var first=BenchmarkCatalog.All.First();var grouped=BenchmarkCatalog.Group(new[]{first,first,first with{Fps=100,Observation="independent"}}).Single();Check(grouped.Samples.Length==2&&Math.Abs(grouped.Mean-(first.Fps+100)/2)<.001,"Duplicate counted / mean wrong");Check(BenchmarkCatalog.Group(new[]{first,first with{Version="Different",Observation="x"},first with{FrameGeneration="on",Observation="y"}}).Length==3,"Incompatible benchmark cases merged");
            if(ui){
                using var settings=new SettingsForm("123","key",(_,_,_,_)=>Task.CompletedTask,()=>{},healthAction:_=>{});settings.Show();Application.DoEvents();foreach(string label in new[]{"Запуск и трей","Оформление","Уведомления","Обновления","Данные и помощь","Ярлыки","Что нового","Профиль Steam"}){Children(settings).OfType<ModernButton>().Single(b=>b.Text==label).PerformClick();Application.DoEvents();Check(Children(settings).OfType<ModernButton>().Any(b=>b.IsNavigation&&b.IsActive&&b.Text==label),"Settings selection missing: "+label);}Check(Children(settings).OfType<TextBox>().Any(t=>t.Text=="123"),"Steam input lost during navigation");
                using var perf=new PerformanceForm(new[]{game},game,(_,p)=>{game.Performance=p.Copy();return true;});perf.SetSnapshot(PcSnapshot.Read());perf.Show();Application.DoEvents();Children(perf).OfType<ModernButton>().Single(b=>b.Text=="Графика").PerformClick();Application.DoEvents();Check(Children(perf).OfType<ComboBox>().Count(c=>c.Visible)>=3,"Native graphics controls missing");Children(perf).OfType<ModernButton>().Single(b=>b.Text=="Скорость").PerformClick();Children(perf).OfType<ModernButton>().Single(b=>b.Text=="Сохранить").PerformClick();Check(game.Performance.NativeOptions["/graphics|TextureQuality"]=="Low","Native preset/save failed");
                var flags=BindingFlags.Instance|BindingFlags.NonPublic;var pick=(ComboBox)typeof(PerformanceForm).GetField("gamePicker",flags)!.GetValue(perf)!;Check(pick.Width>perf.Width/2,"Game picker not filling row");
                using var launcher=new Form1(Path.Combine(root,"library"),false);launcher.Show();Application.DoEvents();var sidebar=Children(launcher).OfType<ModernButton>().Where(b=>b.IsNavigation).ToArray();Check(sidebar.Length>=9,"Launcher categories lost");var add=Children(launcher).OfType<ModernButton>().Single(b=>b.Text=="Добавить ▾");Check(add.Visible,"Add menu unreachable");Check(Children(launcher).OfType<ModernButton>().Any(b=>b.Text=="Ещё ▾"&&b.Visible),"Library management menu missing");
                var dump=Children(settings).OfType<FlowLayoutPanel>().Where(p=>p.Visible).Select(p=>$"FLOW {p.ClientSize} display={p.DisplayRectangle} h={p.HorizontalScroll.Visible}\n"+string.Join("\n",p.Controls.Cast<Control>().Select(c=>$"{c.GetType().Name} {c.Text} bounds={c.Bounds} preferred={c.PreferredSize} max={c.MaximumSize}")));Directory.CreateDirectory("artifacts/redesign");File.WriteAllLines("artifacts/redesign/flow-layout.txt",dump);
                launcher.ClosePrompt=()=>(CloseBehavior.Exit,false);launcher.Close();
            }
        }finally{Directory.Delete(root,true);}
        Console.WriteLine($"PASS: {checks} redesign checks: settings preservation/routes, granular Unreal/current values, Cyberpunk schema/types/ranges/exact rollback, native presets, benchmark provenance/grouping/variants and preserved launcher categories. Fixtures only.");
    }
}
